-- frikfrik protected build
return (function()
local LU="https://raw.githubusercontent.com/TitlePlugins/frikfrik/main/license.txt"
local LV="FRIKFRIK_OK_2026"
local ok_lic, lic = pcall(function() return game:HttpGet(LU .. "?t=" .. tostring(math.random(1, 1000000000)), true) end)
if ok_lic and type(lic) == "string" and #lic > 0 then
    local trimmed = lic:gsub("%s+$", "")
    if trimmed ~= LV then
        error("[frikfrik] license mismatch", 0)
    end
end
local D=""
local K="L4mD_uCkfr1k2026!_$xz9p#Q@7Wj^vR_T_K3y_PrTct"
-- Pre-build per-byte key table for fast lookup
local klen = #K
local kb = {}
for i = 1, klen do kb[i] = string.byte(K, i) end
-- Single-pass gsub: each "%x%x" -> XOR'd byte char (gsub runs at C speed)
local idx = 0
local bxor = bit32.bxor
local sc = string.char
local tn = tonumber
local code = D:gsub("%x%x", function(pair)
    idx = idx + 1
    return sc(bxor(tn(pair, 16), kb[((idx - 1) % klen) + 1]))
end)
local fn, err = loadstring(code, "main")
if not fn then error("[frikfrik] loadstring fail: " .. tostring(err), 0) end
return fn()
end)()
